arguments.file_text:
@namespace sv_b181df515af44f239f28e40786ac9988.Components.Pages.Settings
@using sv_b181df515af44f239f28e40786ac9988.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h3>Security</h3>

    @if (_loading)
    {
        <p class="text-muted">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
            </button>

            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>

                    @if (_passwordError is not null)
                    {
                        <div class="alert alert-danger" role="alert">@_passwordError</div>
                    }
                    @if (_passwordSuccess is not null)
                    {
                        <div class="alert alert-success fade-in" role="alert">@_passwordSuccess</div>
                    }

                    <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="security-card">
            <div class="toggle-row">
                <div class="toggle-info">
                    <span class="toggle-label">Two-Factor Authentication</span>
                    <span class="toggle-description">
                        @if (_twoFactorEnabled)
                        {
                            <span class="status-badge enabled">● Enabled</span>
                        }
                        else
                        {
                            <span class="status-badge disabled">● Disabled</span>
                        }
