@namespace sv_b181df515af44f239f28e40786ac9988.Components.Pages.Settings
@using sv_b181df515af44f239f28e40786ac9988.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h3>Security</h3>

    @if (_loading)
    {
        <p class="text-muted">Loading security settings...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>🔑 Change Password</span>
                <span class="panel-chevron @(_passwordPanelOpen ? "open" : "")">▶</span>
            </button>

            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="_confirmPassword" />
                    </div>

                    @if (_passwordError is not null)
                    {
                        <div class="alert alert-danger" role="alert">@_passwordError</div>
                    }
                    @if (_passwordSuccess is not null)
                    {
                        <div class="alert alert-success fade-in" role="alert">@_passwordSuccess</div>
                    }

                    <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @(_changingPassword ? "Updating..." : "Update Password")
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="security-card">
            <div class="toggle-row">
                <div class="toggle-info">
                    <span class="toggle-label">Two-Factor Authentication</span>
                    <span class="toggle-description">
                        @if (_twoFactorEnabled)
                        {
                            <span class="status-badge enabled">● Enabled</span>
                        }
                        else
                        {
                            <span class="status-badge disabled">● Disabled</span>
                        }
                    </span>
                </div>
                <label class="toggle-switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="toggle-slider"></span>
                </label>
            </div>

            @if (_settings?.LastPasswordChange is not null)
            {
                <p class="text-muted small mt-2 mb-0">
                    Last password change: @_settings.LastPasswordChange.Value.ToString("MMMM d, yyyy")
                </p>
            }
        </div>

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h5>Active Sessions</h5>
            @if (_settings?.Sessions.Count > 0)
            {
                <div class="table-responsive">
                    <table class="table table-hover">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in _settings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@FormatLastActive(session.LastActive)</td>
                                    <td>
                                        @if (session != _settings.Sessions[0])
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => PromptRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-success">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
            else
            {
                <p class="text-muted">No active sessions found.</p>
            }
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-backdrop" @onclick="CancelRevoke">
                <div class="confirm-dialog" @onclick:stopPropagation="true">
                    <h5>Revoke Session</h5>
                    <p>
                        Are you sure you want to revoke the session on
                        <strong>@_sessionToRevoke.Device</strong> from
                        <strong>@_sessionToRevoke.Location</strong>?
                    </p>
                    <div class="dialog-actions">
                        <button class="btn btn-outline-secondary" @onclick="CancelRevoke" disabled="@_revoking">
                            Cancel
                        </button>
                        <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                            @(_revoking ? "Revoking..." : "Revoke Session")
                        </button>
                    </div>
                </div>
            </div>
        }

        @if (_revokeMessage is not null)
        {
            <div class="alert alert-success mt-3 fade-in" role="alert">@_revokeMessage</div>
        }
    }
</section>

@code {
    private bool _loading = true;
    private SecuritySettings? _settings;
    private bool _twoFactorEnabled;

    // Password change state
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private string? _passwordError;
    private string? _passwordSuccess;

    // Session revoke state
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;
    private string? _revokeMessage;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_currentPassword) ||
            string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "Please fill in all password fields.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        _changingPassword = true;

        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordSuccess = "Password updated successfully!";
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordError = $"Failed to change password: {ex.Message}";
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _revokeMessage = null;
    }

    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;

        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _revokeMessage = $"Session on {_sessionToRevoke.Device} has been revoked.";

            // Refresh sessions
            _settings = await SettingsService.GetSecuritySettingsAsync();
        }
        catch (Exception ex)
        {
            _revokeMessage = $"Failed to revoke session: {ex.Message}";
        }
        finally
        {
            _revoking = false;
            _sessionToRevoke = null;
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        return diff.TotalMinutes < 5 ? "Just now"
            : diff.TotalHours < 1 ? $"{(int)diff.TotalMinutes}m ago"
            : diff.TotalDays < 1 ? $"{(int)diff.TotalHours}h ago"
            : lastActive.ToString("MMM d, yyyy");
    }
}

