@namespace sv_b181df515af44f239f28e40786ac9988.Components.Pages.Settings
@using sv_b181df515af44f239f28e40786ac9988.Services
@inject ISettingsService SettingsService

<section class="settings-section">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <p class="text-muted">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <!-- Theme -->
            <div class="option-group">
                <h5>Theme</h5>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-card @(_theme == theme.Value ? "selected" : "")">
                            <input type="radio" name="theme" value="@theme.Value"
                                   checked="@(_theme == theme.Value)"
                                   @onchange="() => _theme = theme.Value" />
                            <span class="radio-icon">@theme.Icon</span>
                            <span>@theme.Label</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="option-group">
                <h5>Font Size</h5>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-card @(_fontSize == size.Value ? "selected" : "")">
                            <input type="radio" name="fontSize" value="@size.Value"
                                   checked="@(_fontSize == size.Value)"
                                   @onchange="() => _fontSize = size.Value" />
                            <span style="font-size: @size.Preview">Aa</span>
                            <span>@size.Label</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="option-group">
                <h5>Language</h5>
                <select class="form-select" @bind="_language" style="max-width: 300px;">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                    <option value="pt">Português</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="option-group">
                <div class="toggle-row">
                    <div class="toggle-info">
                        <span class="toggle-label">Compact Mode</span>
                        <span class="toggle-description">Reduce spacing and padding for a denser layout</span>
                    </div>
                    <label class="toggle-switch">
                        <input type="checkbox" @bind="_compactMode" />
                        <span class="toggle-slider"></span>
                    </label>
                </div>
            </div>

            <!-- Live Preview -->
            <div class="option-group">
                <h5>Preview</h5>
                <div class="live-preview @GetPreviewClasses()">
                    <div class="preview-header">
                        <strong>Sample Card</strong>
                    </div>
                    <p class="preview-body">
                        This is how your content will look with the selected appearance settings.
                        The theme, font size, and compact mode are reflected here.
                    </p>
                    <div class="preview-actions">
                        <span class="preview-btn primary">Primary Action</span>
                        <span class="preview-btn secondary">Secondary</span>
                    </div>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_successMessage is not null)
            {
                <div class="alert alert-success mt-3 fade-in" role="alert">
                    @_successMessage
                </div>
            }

            @if (_errorMessage is not null)
            {
                <div class="alert alert-danger mt-3" role="alert">
                    @_errorMessage
                </div>
            }
        </div>
    }
</section>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _successMessage;
    private string? _errorMessage;

    private string _theme = "light";
    private string _fontSize = "medium";
    private string _language = "en";
    private bool _compactMode;

    private record ThemeOption(string Value, string Label, string Icon);
    private record FontSizeOption(string Value, string Label, string Preview);

    private static readonly ThemeOption[] _themes =
    [
        new("light", "Light", "☀️"),
        new("dark", "Dark", "🌙"),
        new("system", "System", "💻"),
    ];

    private static readonly FontSizeOption[] _fontSizes =
    [
        new("small", "Small", "0.8rem"),
        new("medium", "Medium", "1rem"),
        new("large", "Large", "1.25rem"),
    ];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_theme} preview-font-{_fontSize}";
        if (_compactMode)
            classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _successMessage = null;
        _errorMessage = null;

        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _successMessage = "Appearance settings saved!";
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to save settings: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}

.settings-section {
    max-width: 700px;
}

.settings-section h3 {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.option-group {
    margin-bottom: 1.75rem;
}

.option-group h5 {
    font-weight: 600;
    margin-bottom: 0.75rem;
}

.radio-group {
    display: flex;
    gap: 0.75rem;
}

.radio-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    padding: 1rem 1.5rem;
    border: 2px solid #dee2e6;
    border-radius: 10px;
    cursor: pointer;
    transition: border-color 0.15s, background 0.15s;
    font-size: 0.9rem;
}

.radio-card input[type="radio"] {
    display: none;
}

.radio-card:hover {
    border-color: #adb5bd;
}

.radio-card.selected {
    border-color: #0d6efd;
    background: #e7f1ff;
}

.radio-icon {
    font-size: 1.5rem;
}

/* Toggle (reused pattern) */
.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.toggle-info {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
}

.toggle-label {
    font-weight: 500;
}

.toggle-description {
    font-size: 0.82rem;
    color: #6c757d;
}

.toggle-switch {
    position: relative;
    display: inline-block;
    width: 48px;
    height: 26px;
    flex-shrink: 0;
}

.toggle-switch input {
    opacity: 0;
    width: 0;
    height: 0;
}

.toggle-slider {
    position: absolute;
    cursor: pointer;
    inset: 0;
    background-color: #ccc;
    border-radius: 26px;
    transition: 0.2s;
}

.toggle-slider::before {
    content: "";
    position: absolute;
    height: 20px;
    width: 20px;
    left: 3px;
    bottom: 3px;
    background-color: white;
    border-radius: 50%;
    transition: 0.2s;
}

.toggle-switch input:checked + .toggle-slider {
    background-color: #0d6efd;
}

.toggle-switch input:checked + .toggle-slider::before {
    transform: translateX(22px);
}

/* Live Preview */
.live-preview {
    border: 1px solid #dee2e6;
    border-radius: 10px;
    padding: 1.25rem;
    transition: all 0.3s;
}

.live-preview.preview-theme-light {
    background: #ffffff;
    color: #212529;
}

.live-preview.preview-theme-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.live-preview.preview-theme-system {
    background: #f0f4f8;
    color: #2d3748;
    border-color: #cbd5e0;
}

.live-preview.preview-font-small {
    font-size: 0.8rem;
}

.live-preview.preview-font-medium {
    font-size: 1rem;
}

.live-preview.preview-font-large {
    font-size: 1.2rem;
}

.live-preview.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-header {
    margin-bottom: 0.5rem;
    font-size: 1.1em;
}

.preview-body {
    margin-bottom: 0.75rem;
    opacity: 0.85;
}

.preview-actions {
    display: flex;
    gap: 0.5rem;
}

.preview-btn {
    padding: 0.3rem 0.85rem;
    border-radius: 6px;
    font-size: 0.85em;
    font-weight: 500;
}

.preview-btn.primary {
    background: #0d6efd;
    color: white;
}

.preview-btn.secondary {
    background: #e9ecef;
    color: #495057;
}

.live-preview.preview-theme-dark .preview-btn.secondary {
    background: #374151;
    color: #e0e0e0;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

